/* ── 시트 탭 바 (엑셀식) ──────────────────────────── */
#sheetbar{
  position:fixed;bottom:26px;left:0;right:0;height:30px;z-index:1000;
  background:#232327;display:flex;align-items:flex-end;padding:0 8px;gap:2px;
  overflow-x:auto;overflow-y:hidden;scrollbar-width:none;
  border-top:1px solid rgba(255,255,255,.07);
}
#sheetbar::-webkit-scrollbar{display:none;}
.sht{
  display:flex;align-items:center;gap:6px;flex-shrink:0;
  padding:5px 14px;font-size:12px;color:rgba(255,255,255,.55);
  background:rgba(255,255,255,.04);border:none;border-radius:6px 6px 0 0;
  cursor:pointer;white-space:nowrap;max-width:180px;
}
.sht:hover{background:rgba(255,255,255,.1);color:rgba(255,255,255,.8);}
.sht.active{background:var(--bg);color:#222;font-weight:700;}
.sht .sht-x{border:none;background:none;color:inherit;opacity:.45;cursor:pointer;font-size:11px;padding:0 1px;line-height:1;}
.sht .sht-x:hover{opacity:1;color:#E33;}
.sht-add{flex-shrink:0;border:none;background:none;color:rgba(255,255,255,.5);font-size:14px;font-weight:700;cursor:pointer;padding:4px 10px;border-radius:5px;}
.sht-add:hover{background:rgba(255,255,255,.12);color:#fff;}
/* ── 읽기 전용 모드 (관리자 잠금) ─────────────────── */
body.ro .nact{display:none!important;}
body.ro .adm-only{display:none!important;}
body.ro .nd{cursor:default;}
body.ro .nd .mr{cursor:default;}
body.ro .sfl-ex-btn{display:none;}
#ro-badge{color:#FFB347;font-weight:600;}
/* 파일 재연결 배너 */
#file-banner{
  position:fixed;top:58px;left:50%;transform:translateX(-50%);z-index:1500;
  background:var(--dark);color:#fff;border:1px solid rgba(64,210,167,.5);
  border-radius:8px;padding:8px 14px;font-size:13px;display:none;
  align-items:center;gap:10px;box-shadow:0 4px 16px rgba(0,0,0,.3);
}
#file-banner.show{display:flex;}
#file-banner button{padding:5px 14px;border:none;border-radius:5px;background:var(--mint);
  color:var(--dark);font-weight:700;font-size:12px;cursor:pointer;}
/* 비밀번호 모달 */
#pwov{position:fixed;inset:0;background:rgba(0,0,0,.5);z-index:4000;display:none;align-items:center;justify-content:center;}
#pwov.show{display:flex;}
#pwmodal{background:#fff;border-radius:12px;width:360px;padding:24px 26px;box-shadow:0 8px 40px rgba(0,0,0,.35);}
#pwmodal h3{font-size:15px;font-weight:700;color:#2C2C2C;margin-bottom:14px;}
#pw-status{font-size:12px;margin-bottom:10px;min-height:16px;color:#CC3333;}
#present-exit{display:none;position:fixed;top:10px;right:14px;z-index:5000;padding:7px 14px;border-radius:6px;border:1px solid rgba(255,255,255,.3);background:rgba(30,30,30,.85);color:#fff;font-size:12px;font-weight:600;cursor:pointer;}
body.present #present-exit{display:block;}
body.present #topbar,body.present #tb-reveal,body.present #stbar,body.present #lint-panel,body.present #cmp-panel,body.present .nact,body.present .anchor-dot,body.present .dd,body.present #statsfl,body.present #sheetbar{display:none!important;}
body.present #wrap,body.present #grid-bg{top:0!important;bottom:0!important;}
.nd.srch-hit{outline:3px solid #FFB347;outline-offset:2px;}
.nd.srch-hit.srch-cur{outline:4px solid #FF7A00;outline-offset:2px;}
.mr.srch-row{background:#FFF7B0!important;}
#srch-box{display:inline-flex;align-items:center;gap:6px;}
#srch-input{width:190px;padding:3px 8px;border-radius:5px;border:1px solid rgba(255,255,255,.3);font-size:12px;}
#srch-count{color:#fff;font-size:12px;min-width:36px;}
body.present #srch-box,body.present #srch-btn{display:none!important;}
#treeview{position:fixed;top:50px;left:0;bottom:56px;width:360px;max-width:calc(100vw - 32px);z-index:1200;background:#fff;color:#222;box-shadow:2px 0 14px rgba(0,0,0,.3);display:none;flex-direction:column;font-size:13px;}
#topbar.tb-hidden ~ #treeview,#treeview.tv-notb{top:0;}
#treeview.tv-open{display:flex!important;}
.tv-head{flex:none;display:flex;align-items:center;justify-content:space-between;padding:10px 12px;border-bottom:1px solid #eee;font-weight:700;}
.tv-close{border:0;background:none;cursor:pointer;font-size:15px;color:#555;}
.tv-hbtns{display:flex;align-items:center;gap:6px;}
.tv-txtbtn,.tv-copy{border:1px solid #ccc;background:#fff;border-radius:5px;padding:3px 9px;font-size:12px;cursor:pointer;color:#333;}
.tv-txtbtn[aria-pressed="true"]{background:#2a6a4a;border-color:#2a6a4a;color:#fff;}
.tv-text{flex:1;display:flex;flex-direction:column;min-height:0;padding:8px 10px;gap:6px;}
.tv-tbar{display:flex;align-items:center;gap:10px;font-size:12px;}
.tv-copied{color:#2a6a4a;font-size:12px;}
.tv-ta{flex:1;min-height:0;width:100%;box-sizing:border-box;font:12px/1.5 Consolas,'Noto Sans KR',monospace;white-space:pre;resize:none;border:1px solid #ddd;border-radius:5px;padding:6px;color:#222;}
.tv-acts{display:none;margin-left:auto;gap:2px;flex:none;}
.tv-row:hover .tv-acts,.tv-row:focus-within .tv-acts,.tv-row.tv-sel .tv-acts{display:inline-flex;}
.tv-act{border:1px solid #d0d6d2;background:#fff;border-radius:4px;width:22px;height:22px;padding:0;font-size:12px;line-height:20px;cursor:pointer;color:#2a5a40;}
.tv-act:disabled{opacity:.35;cursor:default;}
.tv-body{flex:1;overflow-y:auto;padding:4px 0;}
.tv-row,.tv-mem{display:flex;align-items:center;gap:6px;padding:4px 10px;white-space:nowrap;}
.tv-row:hover{background:#f3f6f4;}
.tv-row.tv-sel{background:#e3efe8;box-shadow:inset 3px 0 0 #2a6a4a;}
.tv-tog{width:14px;flex:none;cursor:pointer;color:#666;text-align:center;}
.tv-title{cursor:pointer;overflow:hidden;text-overflow:ellipsis;font-weight:600;}
.tv-title:hover{text-decoration:underline;}
.tv-cnt{cursor:pointer;font-size:11px;color:#2a6a4a;background:#e6f2ec;border-radius:8px;padding:0 6px;flex:none;}
.tv-mem{color:#222;font-size:12px;}
.tv-mem .tv-sub{color:#999;}
.tv-head2{padding:10px 12px 4px;font-size:11px;font-weight:700;color:#8a6d00;border-top:1px solid #eee;margin-top:6px;}
body.present #treeview,body.present #btn-tree{display:none!important;}
@media print{#treeview,#treeview.tv-open{display:none!important;}}
#print-stats{display:none;}
#chart-head{position:absolute;display:none;height:36px;line-height:36px;font-size:20px;font-weight:700;color:#222;white-space:nowrap;overflow:hidden;pointer-events:none;}  /* 조직도 이름 · 기준일 (철님 10-20) - 차트 좌표의 윗 띠, 인쇄·PNG와 같은 자리 */
#print-head{display:none;}
#print-pages{display:none;}
#prov{position:fixed;inset:0;background:rgba(0,0,0,.35);display:none;align-items:center;justify-content:center;z-index:3000;}
#prov.show{display:flex;}
.prmodal{background:#fff;border-radius:12px;padding:18px 22px 16px;width:360px;max-width:calc(100vw - 32px);box-shadow:0 8px 40px rgba(0,0,0,.3);}
.prmodal h3{font-size:15px;font-weight:700;color:#222;margin:0 0 12px;}
.pr-row{display:flex;align-items:center;gap:8px;padding:9px 10px;border:1px solid #DADADA;border-radius:8px;margin-bottom:6px;cursor:pointer;font-size:13px;color:#222;}
.pr-row:has(input:checked){border-color:#3A9E85;background:#F2FBF8;}
.pr-e{margin-left:auto;font-size:12px;color:#555;white-space:nowrap;}
.pr-note{font-size:11px;color:#666;margin:8px 0 14px;line-height:1.5;}
.pr-foot{display:flex;justify-content:flex-end;gap:8px;}
@media print{
  #print-head{display:block;position:fixed;font-weight:700;color:#222;white-space:nowrap;overflow:hidden;z-index:50;line-height:1;}
  #print-stats{display:block;position:fixed;left:20px;top:20px;width:150px;box-sizing:border-box;background:#fff;border:1px solid #d0d0d0;font-size:11px;color:#333;z-index:50;}
  #print-stats .ps-hd{background:#2b2f36;color:#fff;font-weight:700;font-size:12px;padding:5px 10px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
  #print-stats .ps-row{display:flex;align-items:center;gap:6px;padding:2px 10px;}
  #print-stats .ps-row i{width:8px;height:8px;flex:none;}
  #print-stats .ps-row span{flex:1;}
  #print-stats .ps-tot{display:flex;justify-content:space-between;font-weight:700;font-size:12px;border-top:1px solid #e4e4e4;margin:4px 8px 0;padding:4px 2px 6px;}
  #print-stats .ps-ex{color:#999;font-size:10px;padding:2px 10px;}
}
@media print{
  #srch-box,#srch-btn{display:none!important;}
  .nd.srch-hit,.nd.srch-hit.srch-cur{outline:none!important;}
  .mr.srch-row{background:inherit!important;}
  body.cmp-noout .mr[data-cmp]{background:inherit!important;}
  body.cmp-noout .mr[data-cmp]::after{content:none!important;display:none!important;}
  body.cmp-noout .nd[data-cmp]{outline:none!important;}
  @page{size:A4 landscape;margin:0}
  body{-webkit-print-color-adjust:exact;print-color-adjust:exact;}
  *{-webkit-print-color-adjust:exact;print-color-adjust:exact;}
  #topbar,#tb-reveal,#stbar,#lint-panel,#cmp-panel,#statsfl,#sheetbar,.dd,#present-exit,#ctxmenu,#grid-bg,[id$="ov"],.modal,.overlay{display:none!important;}
  html,body{width:1123px;height:794px;overflow:hidden!important;margin:0;background:#fff;}
  #wrap{position:static!important;overflow:visible!important;top:0!important;left:0!important;right:auto!important;bottom:auto!important;width:1123px;height:794px;}
  #canvas{min-width:0!important;min-height:0!important;}
}

.ctog{position:absolute;left:50%;top:100%;transform:translateX(-50%) scale(var(--ctog-k,1));transform-origin:50% 0;min-width:18px;height:18px;padding:0 4px;box-sizing:border-box;border-radius:9px;border:0;background:#3a3a3a;color:#fff;font:11px/16px sans-serif;text-align:center;cursor:pointer;z-index:5;opacity:0;visibility:hidden;pointer-events:none;transition:opacity .15s;}
/* 가로 배치(posOrient right/left)에서는 자식이 있는 쪽 가장자리에, 세로 중앙으로 — 멤버 행을 덮지 않도록 가장자리 바깥에 붙인다 */
.ctog-r{left:100%;top:50%;transform:translateY(-50%) scale(var(--ctog-k,1));transform-origin:0 50%;}
.ctog-l{left:auto;right:100%;top:50%;transform:translateY(-50%) scale(var(--ctog-k,1));transform-origin:100% 50%;}
.nd:hover .ctog,.ctog.ctog-on{opacity:1;visibility:visible;pointer-events:auto;}
.ctog:hover{background:#000;}
@media print{.ctog,#btn-expand-all{display:none!important;}}
 @media print{@page{size:A4 landscape;margin:0} html,body{width:1123px!important;height:794px!important;} #wrap{width:1123px!important;height:794px!important;}}

a3.css:
/* ── Brand Colors ─────────────────────────────── */
:root {
  --dark:   #2C2C2C;
  --gray:   #4F4F4F;
  --mint:   #40D2A7;
  --coral:  #FF8770;
  --sky:    #60DCF8;
  --bg:     #ECEEF3;
  --white:  #FFFFFF;
  --border: #E2E4EA;
  --nw: 228px;
  --hh: 70px;
  --mh: 50px;
  --fs-en: 12px;
  --fs-ko: 10px;
  --fs-mn: 11px;
  --fs-mf: 9px;
  --lh-h: 1.2;
  --lh-c: 1.2;
  --band-w: 12px;
  --stroke-w: 1.8;
  --stroke-dash-w: 1.5;
  --card-radius: 8px;
  --shadow-a:    0.11;
  --fs-mr2: 9px;
  --fs-ma:  9px;
  /* 카드 헤더 배경 */
  --hdr-top:  #1A1A1A; --hdr-l1: #2C2C2C;
  --hdr-l2:   #383838; --hdr-l3: #424242;
  --hdr-l4:   #4A4A4A; --hdr-l5: #525252; --hdr-tf: #30304A;
  --hdr-side: #323232;
  /* 타입별 기본 띠색 */
  --band-top: #40D2A7; --band-l1: #40D2A7;
  --band-l2:  #60DCF8; --band-l3: #60DCF8;
  --band-l4:  #A78BFA; --band-l5: #A78BFA; --band-tf: #FF8770;
  --band-side:#FF8770;
  /* 카드 본문 */
  --card-bg:    #FFFFFF;
  --row-even:   #FAFBFD;
  --row-border: #F2F3F6;
  /* 연결선 */
  --conn-solid: #7D879A;
  --conn-dash:  #FF8770;
  /* 그리드 */
  --grid-dot:   #B0B6C4;
  /* 플로팅 패널 / 상태바 */
  --stats-bg:   #1C1C20;
  --stbar-bg:   #1A1A1A;
  /* 텍스트 */
  --txt-hdr-en: #FFFFFF;
  --txt-hdr-ko: #F4F4F4;
  --txt-mn:     #222222;
  --txt-mf:     #666666;
  --txt-mr2:    #707070;
  --txt-ma:    #5F6F91;
  /* 상태 */
  --st-active:  #40D2A7; --st-joining: #60DCF8;
  --st-leaving: #FF8770; --st-needed:  #FFB347; --st-hiring: #A78BFA;
}
*{box-sizing:border-box;margin:0;padding:0;}
body{font-family:'Noto Sans KR',-apple-system,sans-serif;background:var(--bg);overflow:hidden;height:100vh;user-select:none;}

/* ── Topbar ───────────────────────────────────────── */
#topbar{
  position:fixed;top:0;left:0;right:0;height:50px;z-index:1000;
  background:var(--dark);color:#fff;
  display:flex;align-items:center;padding:0 18px;gap:9px;
  box-shadow:0 2px 10px rgba(0,0,0,.4);
  overflow-x:auto;overflow-y:hidden;scrollbar-width:none;
}
#topbar::-webkit-scrollbar{display:none;}
#topbar>*{flex-shrink:0;}
.tl{font-size:15px;font-weight:800;letter-spacing:2px;color:var(--mint);white-space:nowrap;}
.tsub{font-size:12px;color:rgba(255,255,255,.62);flex:1;margin-left:8px;white-space:nowrap;min-width:0;overflow:hidden;text-overflow:ellipsis;flex-shrink:1;}
.tb{white-space:nowrap;}
.tb{padding:6px 13px;border-radius:5px;border:none;cursor:pointer;font-size:12px;font-weight:600;transition:.15s;}
.tb-g{background:rgba(255,255,255,.1);color:#fff;border:1px solid rgba(255,255,255,.2);}
.tb-g:hover{background:rgba(255,255,255,.2);}
.tb-m{background:var(--mint);color:var(--dark);}
.tb-m:hover{filter:brightness(1.1);}
.tb.act{background:var(--coral)!important;color:#fff!important;}
.tdv{width:1px;height:22px;background:rgba(255,255,255,.15);margin:0 3px;}
#topbar.tb-hidden{display:none;}
.tb-arrow{background:transparent;border:none;color:#fff;cursor:pointer;font-size:12px;line-height:1;padding:5px 7px;border-radius:5px;transition:.15s;}
.tb-arrow:hover{background:rgba(255,255,255,.15);}
#tb-hide{margin-right:12px;}
#topbar>.tsub{flex-shrink:1;}
#topbar.tb-tight{gap:5px;}
#topbar.tb-tight .tb{padding:6px 9px;}
#topbar.tb-compact .tdv{display:none;}
#topbar.tb-compact .tb[data-icon]{font-size:0;padding:6px 9px;}
#topbar.tb-compact .tb[data-icon]::before{content:attr(data-icon);font-size:12px;}
#tb-more-panel{position:fixed;top:54px;right:8px;z-index:1050;display:none;flex-direction:column;align-items:stretch;gap:6px;
  background:var(--dark);border:1px solid rgba(255,255,255,.2);border-radius:8px;padding:8px;box-shadow:0 6px 20px rgba(0,0,0,.45);
  max-height:calc(100vh - 64px);max-width:calc(100vw - 16px);overflow-y:auto;}
#tb-more-panel.open{display:flex;}
#topbar,#topbar *,#tb-more-panel,#tb-more-panel *{transition:none!important;}
#tb-more-panel>*{flex-shrink:0;}
#tb-more-panel .tb{text-align:left;}
#tb-more-panel .dd-wrap{display:block;}
#tb-more-panel .dd-wrap>.tb{width:100%;}
body.present #tb-more,body.present #tb-more-panel{display:none!important;}
@media print{#tb-more,#tb-more-panel{display:none!important;}}
#tb-reveal{position:fixed;top:11px;right:30px;z-index:1100;display:none;align-items:center;justify-content:center;width:30px;height:26px;border-radius:6px;background:var(--dark);color:var(--mint);border:1px solid rgba(255,255,255,.2);cursor:pointer;font-size:12px;box-shadow:0 2px 8px rgba(0,0,0,.3);}
#tb-reveal:hover{background:var(--mint);color:var(--dark);}
/* Cloud sync button */
.tb-cloud{max-width:240px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;background:rgba(255,255,255,.08);color:#aaa;border:1px solid rgba(255,255,255,.15);position:relative;}
.tb-cloud.conn{color:#fff;border-color:rgba(64,210,167,.5);background:rgba(64,210,167,.12);}
.cloud-dot{display:none;width:7px;height:7px;border-radius:50%;background:#40D2A7;position:absolute;top:5px;right:5px;box-shadow:0 0 4px #40D2A7;}
.tb-cloud.conn .cloud-dot{display:block;}
/* Cloud modal */
#cloudov{position:fixed;inset:0;background:rgba(0,0,0,.5);z-index:4000;display:none;align-items:center;justify-content:center;}
#cloudov.show{display:flex;}
#cloudmodal{background:#fff;border-radius:12px;width:420px;padding:24px 26px;box-shadow:0 8px 40px rgba(0,0,0,.35);}
#cloudmodal h3{font-size:15px;font-weight:700;color:#2C2C2C;margin-bottom:16px;}
.cm-lbl{font-size:12px;color:#555;display:block;margin-bottom:5px;font-weight:600;}
.cm-inp{width:100%;padding:8px 10px;border:1.5px solid #DDD;border-radius:6px;font-size:13px;margin-bottom:12px;outline:none;transition:.15s;}
.cm-inp:focus{border-color:#40D2A7;}
#cm-status{font-size:12px;margin-bottom:12px;min-height:18px;}
.cm-foot{display:flex;gap:8px;justify-content:flex-end;margin-top:4px;}

/* ── Canvas ───────────────────────────────────────── */
#wrap{
  position:fixed;top:50px;left:0;right:0;bottom:56px;
  overflow:auto;
}
#wrap.panning{cursor:grab;}
#wrap.panning:active{cursor:grabbing;}
#wrap.connect-mode{cursor:crosshair;}
#canvas{
  position:relative;
  transform-origin:0 0;
  min-width:1800px;min-height:1020px;
}
.tfzone{position:absolute;z-index:0;box-sizing:border-box;pointer-events:none;background:rgba(255,193,7,.10);border:2px dashed #c9a227;border-radius:16px;}
.tfzone-t{position:absolute;left:12px;top:6px;font:bold 12px/16px sans-serif;color:#6E5700;white-space:nowrap;}
.tfowner{position:absolute;z-index:0;box-sizing:border-box;height:16px;max-width:200px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font:11px/16px sans-serif;color:#6E5700;pointer-events:none;}
@media print{.tfzone,.tfowner{display:block!important;-webkit-print-color-adjust:exact;print-color-adjust:exact;}}
/* dot grid — fixed overlay, dynamically positioned via JS */
#grid-bg{
  position:fixed;top:50px;left:0;right:0;bottom:56px;
  pointer-events:none;z-index:0;opacity:.5;
  background-image:radial-gradient(circle at 0 0,var(--grid-dot) 1px,transparent 1px);
}

/* ── SVG Connections ──────────────────────────────── */
#svgl{position:absolute;top:0;left:0;pointer-events:none;}
.cpath{fill:none;stroke:var(--conn-solid);stroke-width:var(--stroke-w);}
.cpath-dash{fill:none;stroke:var(--conn-dash);stroke-width:var(--stroke-dash-w);stroke-dasharray:7 4;}
body:not(.printing) #svgl .cpath{stroke-width:max(calc(var(--stroke-w) * 1px),var(--line-min,0px));}  /* 화면을 줄여도 선이 1.3px 아래로 가늘어지지 않게 (철님 10-23) */
body:not(.printing) #svgl .cpath-dash{stroke-width:max(calc(var(--stroke-dash-w) * 1px),var(--line-min,0px));}
@media print{#svgl .cpath{stroke-width:var(--stroke-w)!important;}#svgl .cpath-dash{stroke-width:var(--stroke-dash-w)!important;}}
.cpath-hl-dash{stroke:var(--conn-dash)!important;}
.chit{fill:none;stroke:transparent;stroke-width:14;pointer-events:stroke;cursor:pointer;}
.chit:hover~.cpath,.chit:hover~.cpath-dash{stroke-opacity:.5;}
/* 연결선 선택 하이라이트 */
.cpath-hl{fill:none;stroke:var(--sky);stroke-width:4.5;opacity:.45;}
.cpath-hl-dash{fill:none;stroke:var(--coral);stroke-width:3.5;opacity:.45;stroke-dasharray:7 4;}
.nd.conn-hl{box-shadow:0 0 0 2.5px var(--sky),0 4px 18px rgba(0,0,0,.18)!important;}
/* 앵커 오버레이 */
#anchor-overlay{position:absolute;top:0;left:0;pointer-events:none;z-index:60;}
.anchor-dot{
  position:absolute;width:14px;height:14px;border-radius:50%;
  border:2.5px solid var(--coral);background:rgba(255,255,255,.92);
  transform:translate(-50%,-50%);pointer-events:all;cursor:crosshair;
  transition:.1s;box-shadow:0 1px 5px rgba(0,0,0,.18);
}
.anchor-dot.active{background:var(--coral);}
.anchor-dot.drop-target{border-color:var(--sky);background:rgba(96,220,248,.2);transform:translate(-50%,-50%) scale(1.25);}
/* 드롭다운 메뉴 */
.dd-wrap{position:relative;display:inline-block;}
.dd{position:fixed;z-index:2000;
  background:#fff;border-radius:8px;box-shadow:0 5px 18px rgba(0,0,0,.2);
  padding:4px 0;min-width:130px;border:1px solid rgba(0,0,0,.07);display:none;}
.dd.open{display:block;}
.ddi{display:block;width:100%;padding:9px 15px;text-align:left;border:none;
  background:none;cursor:pointer;font-size:12px;color:#333;white-space:nowrap;}
.ddi:hover{background:#F3F5F9;}
/* 웨이포인트 핸들 */
.way-handle{fill:var(--sky);stroke:#fff;stroke-width:2;cursor:ns-resize;}
/* ── Options Popup ────────────────────────────────── */
#optov{position:fixed;inset:0;background:rgba(0,0,0,.45);z-index:3000;display:none;align-items:flex-start;justify-content:center;padding-top:60px;}
#optov.show{display:flex;}
#optmodal{background:#fff;border-radius:12px;width:520px;max-height:82vh;overflow-y:auto;box-shadow:0 8px 40px rgba(0,0,0,.3);}
.opt-head{padding:16px 22px 12px;border-bottom:1px solid #EEE;display:flex;align-items:center;justify-content:space-between;position:sticky;top:0;background:#fff;z-index:1;}
.opt-head h2{font-size:15px;font-weight:700;color:var(--dark);}
.opt-body{padding:6px 0 16px;}
.opt-sec{padding:10px 22px 4px;}
.opt-sec-title{font-size:10px;font-weight:700;color:#6B6B6B;letter-spacing:1.5px;text-transform:uppercase;margin-bottom:10px;padding-bottom:4px;border-bottom:1px solid #F0F0F0;}
.opt-sec-title[role=button]{cursor:pointer;user-select:none;}
.opt-sec.collapsed>*:not(.opt-sec-title){display:none;}
.opt-sec.collapsed>.opt-sec-title{margin-bottom:0;}
.opt-row{display:flex;align-items:center;gap:10px;margin-bottom:10px;}
.pre-row{display:flex;align-items:center;gap:6px;margin-bottom:6px;}
.pre-name{flex:1;min-width:0;border:1px solid #D0D0D0;border-radius:5px;padding:4px 6px;font-size:12px;}
.pre-b{font-size:11px;padding:4px 8px;border:1px solid #C8C8C8;border-radius:5px;background:#fff;color:#333;cursor:pointer;white-space:nowrap;}
.pre-b:hover:not(:disabled){background:#F2F2F2;}
.pre-b:disabled{opacity:.45;cursor:default;}
.pre-at{font-size:10px;color:#666;width:62px;text-align:right;white-space:nowrap;}
.pre-hint{font-size:11px;color:#666;line-height:1.5;margin-top:2px;}
.opt-lbl{font-size:12px;color:#555;min-width:100px;}
.opt-val{font-size:11px;color:#6B6B6B;min-width:32px;text-align:right;}
.opt-slider{flex:1;accent-color:var(--mint);cursor:pointer;}
.opt-color{width:32px;height:28px;border:1.5px solid #DDD;border-radius:5px;cursor:pointer;padding:2px;}
.opt-color-row{display:flex;align-items:center;gap:8px;margin-bottom:8px;}
.opt-color-lbl{font-size:12px;color:#555;flex:1;}
.opt-color-dot{width:10px;height:10px;border-radius:50%;flex-shrink:0;box-shadow:inset 0 0 0 1px rgba(0,0,0,.18);} /* a white swatch (헤더 제목) was invisible on the panel */
.opt-foot{padding:12px 22px;border-top:1px solid #EEE;display:flex;justify-content:flex-end;gap:8px;}
/* 컬러 헥스 인풋 (피커 + 6자리 텍스트) */
.chex{display:inline-flex;align-items:center;gap:3px;}
.chex-c{width:28px;height:28px;padding:2px;border:1.5px solid #DDD;border-radius:5px;cursor:pointer;flex-shrink:0;}
.chex-hash{font-size:12px;color:#888;user-select:none;line-height:1;}
.chex-t{width:60px;padding:4px 5px;border:1px solid #DDD;border-radius:4px;font-size:12px;font-family:monospace;letter-spacing:1px;text-transform:uppercase;}
.chex-t:focus{border-color:var(--mint);outline:none;}
/* 멤버 상태 드롭다운 (수정 모달 내) */
.mer select{padding:4px 6px;border:1px solid #DDD;border-radius:4px;font-size:11px;background:#fff;cursor:pointer;}
/* 우클릭 컨텍스트 메뉴 */
#ctxmenu{position:fixed;z-index:3000;background:#fff;border-radius:8px;
  box-shadow:0 6px 24px rgba(0,0,0,.22);padding:5px 0;min-width:150px;display:none;}
#ctxmenu.show{display:block;}
.ctx-item{padding:9px 16px;font-size:13px;cursor:pointer;display:flex;align-items:center;gap:8px;color:#333;}
.ctx-item:hover{background:#F5F7FA;}
.ctx-del{color:#CC3333;}

/* ── Node Cards ───────────────────────────────────── */
.nd{
  position:absolute;width:var(--nw);
  background:var(--white);border-radius:var(--card-radius);
  box-shadow:0 2px 8px rgba(0,0,0,var(--shadow-a));
  overflow:visible;transition:box-shadow .2s;  /* 접기 토글(.ctog)이 카드 가장자리 바깥에 걸치므로 모서리 클리핑은 .nh/.nb가 맡는다 */
}
.nd:hover{box-shadow:0 6px 20px rgba(0,0,0,var(--shadow-a));}
.nd{cursor:move;}
.nd.lint-bad{outline:3px solid #dc2626;outline-offset:2px;}
.nd.lint-flash{animation:lintflash .3s ease 3;}
@keyframes lintflash{50%{filter:brightness(1.4);}}
#lint-panel{display:none;position:fixed;z-index:9999;background:#fff;color:#111;border:1px solid #ccc;border-radius:6px;box-shadow:0 4px 16px rgba(0,0,0,.25);padding:8px;width:300px;max-height:60vh;overflow:auto;font-size:12px;}
.lint-item{padding:4px 2px;cursor:pointer;border-top:1px solid #eee;}
.lint-item:hover{background:#fee2e2;}
.nd .mr{cursor:grab;}
.mr[data-cmp]::after{position:absolute;right:2px;top:1px;font-size:9px;line-height:1;padding:1px 3px;border-radius:3px;color:#fff;pointer-events:none;}
.mr[data-cmp="new"]{background:rgba(46,160,67,.18);}
.mr[data-cmp="new"]::after{content:'신규';background:#2ea043;}
.mr[data-cmp="moved"]{background:rgba(56,139,253,.18);}
.mr[data-cmp="moved"]::after{content:'이동';background:#388bfd;}
.mr[data-cmp="changed"]{background:rgba(227,160,8,.22);}
.mr[data-cmp="changed"]::after{content:'변경';background:#d29922;}
.nd[data-cmp="new"]{outline:2px dashed #2ea043;outline-offset:2px;}
#cmp-panel{position:fixed;top:60px;right:12px;z-index:900;background:#fff;color:#222;border:1px solid #ccc;border-radius:6px;box-shadow:0 2px 10px rgba(0,0,0,.2);padding:8px 10px;width:340px;max-height:60vh;overflow:auto;font-size:12px;}
#cmp-panel .cmp-h{display:flex;justify-content:space-between;align-items:center;gap:8px;margin-bottom:6px;}
#cmp-panel .cmp-err{color:#c00;}
#cmp-panel .cmp-cnt{margin-bottom:6px;font-weight:600;}
#cmp-panel{width:380px!important;}
#cmp-panel .cmp-cnt{display:flex;flex-wrap:wrap;gap:4px;font-weight:400;}
#cmp-panel .cmp-chip{background:#f1f3f6;border-radius:10px;padding:1px 8px;font-size:12px;}
#cmp-panel .cmp-chip[data-k=join]{background:#e3f6ee}#cmp-panel .cmp-chip[data-k=leave]{background:#fde8e4}#cmp-panel .cmp-chip[data-k=move]{background:#e6f0fd}#cmp-panel .cmp-chip[data-k=seat]{background:#fff3df}
#cmp-panel .cmp-out{display:block;font-size:12px;color:#555;margin:6px 0 2px;}
#cmp-panel .cmp-sec{margin-top:8px;}
#cmp-panel .cmp-sec-h{font-weight:700;font-size:12px;color:#333;border-bottom:2px solid #d8dde6;padding-bottom:2px;}
#cmp-panel .cmp-tbl{width:100%;border-collapse:collapse;font-size:12px;}
#cmp-panel .cmp-tbl td{padding:3px 4px;border-bottom:1px solid #eee;vertical-align:top;}
#cmp-panel .cmp-tbl td.c0{font-weight:600;white-space:nowrap;}
#cmp-panel .cmp-tbl td.c1{color:#556;}
#cmp-panel .cmp-tbl td.c2{color:#777;}
.mr[data-cmp="seat"]{background:rgba(255,179,71,.22);}
.mr[data-cmp="seat"]::after{content:'공석';background:#e08a00;}
#cmp-panel .cmp-item{cursor:pointer;}
#cmp-panel .cmp-item:hover td{background:#f6f8fb;}
.nd .mr:active{cursor:grabbing;}
.nd .nact button{cursor:pointer;}
.nd.sel{outline:2.5px solid var(--sky);outline-offset:2px;}
.nd.csrc{outline:2.5px solid var(--coral);outline-offset:2px;}

/* Header */
.nh{
  height:var(--hh);padding:8px 12px 8px 16px;
  display:flex;flex-direction:column;justify-content:center;
  cursor:move;position:relative;
  border-radius:var(--card-radius) var(--card-radius) 0 0;overflow:hidden;
}
.nh::before{content:'';position:absolute;left:0;top:0;bottom:0;width:var(--band-w);background:var(--band-color,var(--mint));}
.t-top {--band-color:var(--band-top);} .t-top  .nh{background:var(--hdr-top);}
.t-l1  {--band-color:var(--band-l1);}  .t-l1   .nh{background:var(--hdr-l1);}
.t-l2  {--band-color:var(--band-l2);}  .t-l2   .nh{background:var(--hdr-l2);}
.t-l3  {--band-color:var(--band-l3);}  .t-l3   .nh{background:var(--hdr-l3);} .t-l3 .nh::before{opacity:.7;}
.t-l4  {--band-color:var(--band-l4);}  .t-l4   .nh{background:var(--hdr-l4);} .t-l4 .nh::before{opacity:.6;}
.t-l5  {--band-color:var(--band-l5);}  .t-l5   .nh{background:var(--hdr-l5);} .t-l5 .nh::before{opacity:.5;}
.t-tf  {--band-color:var(--band-tf);}  .t-tf   .nh{background:var(--hdr-tf);}
.t-side{--band-color:var(--band-side);}.t-side .nh{background:var(--hdr-side);}

.nen{font-size:var(--fs-en);font-weight:700;color:var(--txt-hdr-en);letter-spacing:.6px;text-transform:uppercase;padding-left:2px;line-height:var(--lh-h);}
.nko{font-size:var(--fs-ko);color:var(--txt-hdr-ko);padding-left:2px;margin-top:2px;line-height:var(--lh-h);}

/* Action buttons (hover) */
.nact{position:absolute;top:6px;right:7px;opacity:0;transition:.15s;}
.ncnt{position:absolute;top:calc(3px + var(--cnt-dy,0px));right:calc(36px + var(--cnt-dx,0px));font-size:var(--cnt-fs,9px);line-height:var(--cnt-lh,12px);padding:0 var(--cnt-px,6px);border-radius:8px;background:rgba(0,0,0,.55);color:#fff;box-shadow:inset 0 0 0 1px rgba(255,255,255,.28);pointer-events:none;white-space:nowrap;}  /* 흰 글자 대비 4.5 이상: 흰 헤더 위에서도 4.76 */
.ncnt{z-index:3;}
.ncnt-br{top:calc(var(--hh) - var(--cnt-lh,12px) - 4px + var(--cnt-dy,0px));}
.ncnt.ncnt-mr{top:calc(var(--hh) / 2 - var(--cnt-lh,12px) / 2 + var(--cnt-dy,0px));}
.ncnt.ncnt-badge,body.ro .ncnt.ncnt-badge,body.present .ncnt.ncnt-badge{top:var(--cnt-dy,0px);right:var(--cnt-dx,0px);transform:translate(50%,-50%);z-index:6;}
#mtip{position:fixed;display:none;z-index:99999;background:rgba(20,20,24,.95);color:#fff;font-size:11px;line-height:1.5;padding:7px 10px;border-radius:6px;max-width:260px;pointer-events:none;word-break:break-all;box-shadow:0 2px 8px rgba(0,0,0,.35);}
#mtip b{font-size:12px;}
body.present #mtip{display:none!important;}
@media print{#mtip{display:none!important;}}
.nd:hover .nact{opacity:1;}
.nab{width:22px;height:22px;border-radius:5px;border:none;cursor:pointer;font-size:12px;
     display:flex;align-items:center;justify-content:center;background:rgba(255,255,255,.2);color:#fff;transition:.15s;}
.nab:hover{background:var(--mint);color:var(--dark);}

/* Member rows */
.nb{background:var(--card-bg);border-radius:0 0 var(--card-radius) var(--card-radius);overflow:hidden;}
.nb:empty{height:10px;min-height:10px;position:relative;overflow:visible;}  /* 구성원이 없는 카드: 배치·인쇄·PNG는 머리글 + 10px 흰 마감 (EMPTY_CAP) */
.nb:empty::before{content:'＋';position:absolute;left:0;right:0;top:0;height:34px;display:flex;align-items:center;justify-content:center;background:var(--card-bg);border-radius:0 0 var(--card-radius) var(--card-radius);box-shadow:0 2px 8px rgba(0,0,0,var(--shadow-a));color:#C8CDD8;font-size:15px;}  /* 화면에서는 원래의 ＋ 본문이 마감 위에 겹쳐 보인다 (철님 10-20) - 구성원 끌어다 놓는 자리 */
body.printing .nb:empty::before{display:none!important;}
@media print{.nb:empty::before{display:none!important;}}
.mr{padding:4px 10px 4px calc(var(--band-w) + 8px);height:var(--mh);position:relative;display:flex;align-items:center;gap:0;border-top:1px solid var(--row-border);box-sizing:border-box;overflow:hidden;}
.mr:nth-child(even){background:var(--row-even);}
.nb.mcol{display:grid;padding-left:var(--band-w);background:linear-gradient(var(--band-color,var(--mint)),var(--band-color,var(--mint))) left top/var(--band-w) 100% no-repeat,var(--card-bg);}
/* 본문 색 띠 옵션(OPT.bodyBand): 켜면 1열 카드도 본문에 띠, 끄면 여러 열 카드도 머리글에만 - 열 수와 무관하게 같은 규칙 (철님 10-20) */
body.bodyband .nb{padding-left:var(--band-w);background:linear-gradient(var(--band-color,var(--mint)),var(--band-color,var(--mint))) left top/var(--band-w) 100% no-repeat,var(--card-bg);}
body:not(.bodyband) .nb.mcol{padding-left:0;background:var(--card-bg);}
:where(.nb.mcol)>.mr:nth-child(even){background:none;}
.mr.mr-ev{background:var(--row-even);}
.nb.mcol>.mr[data-cmp="new"]{background:rgba(46,160,67,.18);}
.nb.mcol>.mr[data-cmp="moved"]{background:rgba(56,139,253,.18);}
.nb.mcol>.mr[data-cmp="changed"]{background:rgba(227,160,8,.22);}
.mband{position:absolute;left:0;top:0;bottom:0;width:var(--band-w);}
.mi{flex:1;min-width:0;overflow:hidden;}
.mn-row{display:flex;align-items:flex-end;gap:8px;overflow:hidden;}
.mn{font-size:var(--fs-mn);font-weight:600;color:var(--txt-mn);line-height:var(--lh-c);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;min-width:0;flex-shrink:1;}
.mf{font-size:var(--fs-mf);color:var(--txt-mf);margin-top:1px;line-height:var(--lh-c);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}
.mr2{font-size:var(--fs-mr2);color:var(--txt-mr2);white-space:nowrap;flex-shrink:0;line-height:var(--lh-c);}
.mn-row>.mn:empty,.mn-row>.mr2:empty{display:none;}
.mst{font-size:var(--fs-mr2);line-height:1.2;color:#333;background:#fff;border:1px solid #9A9A9A;border-radius:3px;padding:0 3px;white-space:nowrap;flex-shrink:0;align-self:center;}
.ma{font-size:var(--fs-ma);color:var(--txt-ma);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;line-height:var(--lh-c);margin-top:1px;}
/* Member row drag-and-drop (move between teams) */
.mr[draggable="true"]{cursor:grab;}
.mr[draggable="true"]:active{cursor:grabbing;}
.mr.mr-dragging{opacity:.35;background:#FFF4ED!important;}
.nb.mr-drop-target{background:rgba(64,210,167,.10);box-shadow:inset 0 0 0 2px var(--mint);}
.mr.mr-drop-before{box-shadow:inset 0 2px 0 0 var(--mint)!important;}
.mr.mr-drop-after{box-shadow:inset 0 -2px 0 0 var(--mint)!important;}

/* ── Modal ───────────────────────────────────────── */
#ov{
  position:fixed;inset:0;background:rgba(0,0,0,.5);z-index:2000;
  display:none;align-items:center;justify-content:center;
}
#ov.show{display:flex;}
#modal{
  background:#fff;border-radius:12px;width:480px;max-height:82vh;
  overflow-y:auto;box-shadow:0 20px 60px rgba(0,0,0,.3);
}
.mh2{padding:18px 22px 14px;border-bottom:1px solid #EEE;
     display:flex;align-items:center;justify-content:space-between;}
.mh2 h2{font-size:15px;font-weight:700;color:var(--dark);}
.mcl{background:none;border:none;font-size:20px;cursor:pointer;color:#999;padding:0 4px;}
.mb{padding:18px 22px;}
.mf2{padding:14px 22px;border-top:1px solid #EEE;display:flex;justify-content:flex-end;gap:8px;}
.fg{margin-bottom:14px;}
.fl{font-size:11px;font-weight:600;color:#555;margin-bottom:5px;display:block;}
.fi{width:100%;padding:7px 10px;border:1.5px solid #DDD;border-radius:6px;font-size:13px;color:#333;transition:.15s;}
.fi:focus{outline:none;border-color:var(--mint);}
.fs{width:100%;padding:7px 10px;border:1.5px solid #DDD;border-radius:6px;font-size:13px;background:#fff;cursor:pointer;}
.ml{border:1.5px solid #EBEBEB;border-radius:7px;overflow:hidden;}
.mer{padding:8px 10px;border-bottom:1px solid #F2F2F2;display:flex;flex-direction:column;gap:5px;}
.mer:last-child{border-bottom:none;}
.mer.dragging{opacity:0.4;background:#F5F8FF;}
.mer.drag-over-top{border-top:2px solid var(--mint);}
.mer.drag-over-bot{border-bottom:2px solid var(--mint);}
.mer-r{display:flex;gap:5px;align-items:center;}
.ord-lbl{font-size:11px;color:#777;margin:6px 0 3px;}
.ord-l{border:1.5px solid #EBEBEB;border-radius:7px;overflow:hidden;}
.ord-row{display:flex;align-items:center;gap:6px;padding:5px 8px;border-bottom:1px solid #F2F2F2;font-size:12px;background:#fff;}
.ord-row:last-child{border-bottom:none;}
.ord-row .ord-h{cursor:grab;color:#aaa;}
.ord-row .ord-n{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}
.ord-row button{border:1px solid #DDD;background:#fff;border-radius:4px;font-size:10px;padding:1px 5px;cursor:pointer;}
.ord-row.dragging{opacity:0.4;background:#F5F8FF;}
.ord-row.drag-over-top{border-top:2px solid var(--mint);}
.ord-row.drag-over-bot{border-bottom:2px solid var(--mint);}
.mer input,.mer select{padding:5px 7px;border:1px solid #DDD;border-radius:4px;font-size:12px;background:#fff;}
.mer-name{flex:1;min-width:0;}
.mer-sel{flex:0 0 auto;font-size:11px;}
.mer-drag{cursor:grab;color:#C8CDD8;font-size:15px;padding:0 2px 0 0;line-height:1;user-select:none;flex-shrink:0;}
.mer-drag:hover{color:#888;}
.brm{background:none;border:none;color:#FF6B6B;cursor:pointer;font-size:16px;padding:1px 5px;flex-shrink:0;}
/* 데이터 모달 */
#dataov{position:fixed;inset:0;background:rgba(0,0,0,.45);z-index:3000;display:none;align-items:flex-start;justify-content:center;padding-top:60px;}
#dataov.show{display:flex;}
#datamodal{background:#fff;border-radius:12px;width:540px;max-height:84vh;overflow-y:auto;box-shadow:0 8px 40px rgba(0,0,0,.3);}
.dat-head{padding:16px 22px 12px;border-bottom:1px solid #EEE;display:flex;align-items:center;gap:8px;position:sticky;top:0;background:#fff;z-index:1;}
.dat-head h2{font-size:15px;font-weight:700;color:var(--dark);flex:1;}
.dat-head-lbl{border:none;background:transparent;font-size:15px;font-weight:700;color:var(--dark);flex:1;outline:none;padding:0;}
.dat-head-lbl:focus{border-bottom:2px solid var(--mint);}
.dat-body{padding:0 0 16px;}
.dat-sec{padding:12px 22px 4px;}
.dat-sec-title{font-size:10px;font-weight:700;color:#999;letter-spacing:1.5px;text-transform:uppercase;margin-bottom:10px;padding-bottom:4px;border-bottom:1px solid #F0F0F0;}
.cat-list{display:flex;flex-wrap:wrap;gap:5px;margin-bottom:8px;}
.cat-tag{display:flex;align-items:center;gap:3px;padding:3px 8px 3px 10px;background:#F3F5F9;border-radius:20px;font-size:12px;color:#444;}
.cat-tag .cat-del{background:none;border:none;cursor:pointer;color:#999;font-size:13px;padding:0 1px;line-height:1;}
.cat-tag .cat-del:hover{color:#E33;}
.cat-name-inp{border:none;background:transparent;font-size:12px;color:#444;padding:0 2px;outline:none;min-width:30px;max-width:80px;}
.cat-name-inp:focus{background:#fff;border-radius:3px;}
.drag-hnd{color:#ccc;font-size:13px;cursor:grab;padding:0 2px;user-select:none;line-height:1;flex-shrink:0;}
.drag-hnd:hover{color:#888;}
.drag-over{outline:2px solid var(--mint) !important;border-radius:inherit;}
/* 상태 카테고리 태그 */
.stcat-tag{display:flex;align-items:center;gap:5px;padding:3px 8px 3px 6px;background:#F3F5F9;border-radius:20px;font-size:12px;color:#444;}
.stcat-col{width:18px;height:18px;border:none;border-radius:50%;padding:0;cursor:pointer;background:none;}
.stcat-lbl{border:none;background:transparent;font-size:12px;color:#444;width:62px;padding:1px 2px;outline:none;}
.stcat-lbl:focus{background:#fff;border-radius:3px;}
.stcat-del{background:none;border:none;cursor:pointer;color:#999;font-size:13px;padding:0 1px;line-height:1;}
.stcat-del:hover{color:#E33;}
.stcat-to{display:inline-flex;align-items:center;gap:2px;font-size:11px;color:#667;white-space:nowrap;cursor:pointer;}
.cat-add{display:flex;gap:5px;margin-top:4px;}
.cat-add input{flex:1;padding:5px 9px;border:1.5px solid #DDD;border-radius:6px;font-size:12px;}
.cat-add button{padding:5px 12px;border:none;border-radius:6px;background:var(--mint);color:#fff;font-size:12px;font-weight:600;cursor:pointer;}
/* 현황 그룹 */
.sg-list{display:flex;flex-direction:column;gap:6px;margin-bottom:8px;}
.sg-row{display:flex;align-items:center;gap:6px;padding:7px 10px;background:#F8F9FB;border-radius:7px;}
.sg-name{flex:0 0 80px;padding:3px 6px;border:1px solid #DDD;border-radius:4px;font-size:12px;}
.sg-checks{flex:1;display:flex;flex-wrap:wrap;gap:5px;}
.sg-check{display:flex;align-items:center;gap:3px;font-size:11px;cursor:pointer;}
.sg-del{background:none;border:none;cursor:pointer;color:#BBB;font-size:14px;padding:0 2px;}
.sg-del:hover{color:#E33;}
.sg-add{padding:5px 12px;border:none;border-radius:6px;background:#EEF;color:#558;font-size:12px;font-weight:600;cursor:pointer;width:100%;margin-top:2px;}
/* 플로팅 현황 패널 */
#statsfl{
  position:fixed;top:60px;left:20px;z-index:400;
  background:var(--stats-bg);backdrop-filter:blur(8px);
  border:1px solid rgba(255,255,255,.1);border-radius:10px;
  min-width:244px;padding:10px 14px 10px;
  box-shadow:0 6px 24px rgba(0,0,0,.35);
  cursor:move;user-select:none;color:#fff;font-size:12px;
}
#statsfl-hd{margin-bottom:8px;display:flex;align-items:center;justify-content:space-between;gap:8px;}
#statsfl-tog{border:none;background:transparent;color:inherit;opacity:.7;cursor:pointer;font-size:12px;padding:0 2px;}
#statsfl-tog:hover{opacity:1;}
#statsfl.collapsed #statsfl-tabs,#statsfl.collapsed #statsfl-filter,#statsfl.collapsed #statsfl-body{display:none!important;}
#statsfl.collapsed #statsfl-hd{margin-bottom:0;}
#statsfl-title{font-size:11px;font-weight:700;letter-spacing:.8px;opacity:.6;}
#statsfl-tabs{display:flex;gap:2px;margin-bottom:9px;}
.sfl-tab{flex:1;padding:4px 0;border:1px solid rgba(255,255,255,.14);border-radius:5px;background:rgba(255,255,255,.05);color:rgba(255,255,255,.45);font-size:10px;font-weight:600;cursor:pointer;transition:.15s;}
.sfl-tab:hover{background:rgba(255,255,255,.12);color:rgba(255,255,255,.75);}
.sfl-tab.active{background:rgba(255,255,255,.18);color:#fff;border-color:rgba(255,255,255,.35);}
.sfl-sec{border-top:1px solid rgba(255,255,255,.1);margin-top:7px;padding-top:7px;}
.sfl-sec-lbl{font-size:9px;opacity:.4;letter-spacing:.6px;margin-bottom:4px;}
.sfl-grp-sel{width:100%;background:rgba(255,255,255,.08);color:#fff;border:1px solid rgba(255,255,255,.16);border-radius:5px;font-size:10px;padding:4px 6px;cursor:pointer;}
.sfl-grp-sel option{background:#2a2a30;color:#fff;}
.sfl-row{display:flex;align-items:center;gap:7px;padding:3px 0;}
.sfl-foot{position:sticky;bottom:0;background:var(--stats-bg);padding-bottom:1px;}  /* 목록을 내려도 합계는 늘 보인다 (철님 10-23) */
.sfl-row.sfl-short .sfl-num{color:#FFB347;}  /* 정원보다 현원이 적은 칸 */
.sfl-gap{font-size:10px;font-weight:700;color:#FFB347;white-space:nowrap;flex-shrink:0;}
.sfl-num{white-space:nowrap;flex-shrink:0;}
.sfl-qtog{display:block;width:100%;text-align:left;background:none;border:0;padding:2px 0;color:inherit;font:inherit;font-size:10px;cursor:pointer;}
.sfl-qtog:hover{opacity:.9;}
/* 조회 탭 (철님 10-23) */
.sfl-qchips{display:flex;flex-wrap:wrap;gap:4px;margin-bottom:4px;}
.sfl-qchip{display:inline-flex;align-items:center;gap:2px;padding:2px 3px 2px 7px;border-radius:10px;background:rgba(255,255,255,.14);font-size:10px;}
.sfl-qchip b{font-weight:400;opacity:.6;margin-right:2px;}
.sfl-qx{border:none;background:none;color:inherit;opacity:.65;cursor:pointer;font-size:12px;line-height:1;padding:0 2px;}
.sfl-qx:hover{opacity:1;}
.sfl-qadd{display:flex;gap:4px;margin-bottom:6px;}
.sfl-qadd select{flex:1;min-width:0;}
.sfl-dup.sfl-qsum{text-align:left;opacity:.75;margin:0 0 6px;line-height:1.4;}  /* 같은 항목은 또는, 다른 항목끼리는 그리고 (UIUX A6) */
.sfl-qlist .sfl-sec-lbl{opacity:.55;}
.sfl-qempty{font-size:10px;opacity:.75;padding:2px 0 6px;line-height:1.4;}
.sfl-qclr{border:none;background:none;color:inherit;opacity:.75;cursor:pointer;font-size:10px;text-decoration:underline;padding:2px 4px;}
.sfl-qclr:hover{opacity:1;}
.sfl-qby{display:flex;align-items:center;gap:6px;margin:4px 0 2px;font-size:10px;opacity:.85;}
.sfl-qby select{flex:1;min-width:0;}
.sfl-qhint{font-size:10px;opacity:.5;padding:2px 0 4px;}
.sfl-qsub{font-size:9px;opacity:.5;white-space:nowrap;}
.sfl-qlist{max-width:240px;}
.sfl-dot{width:8px;height:8px;border-radius:50%;flex-shrink:0;}
.sfl-lbl{flex:1;font-size:11px;opacity:.7;}
.sfl-num{font-size:13px;font-weight:700;}
#statsfl-body{max-height:calc(100vh - 160px);overflow-y:auto;}
.sfl-ell{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;min-width:0;}
.sfl-row.cur{background:rgba(255,255,255,.14);border-radius:4px;}
.sfl-row.cur .sfl-lbl{opacity:1;font-weight:700;}
.sfl-sub{font-size:9px;opacity:.5;}
.sfl-cc{font-size:9px;opacity:.6;color:var(--mint);}
.sfl-scopes{display:flex;gap:4px;margin-bottom:6px;}
.sfl-scope{flex:1;padding:3px 0;border:1px solid rgba(255,255,255,.14);border-radius:5px;background:rgba(255,255,255,.05);color:rgba(255,255,255,.5);font-size:10px;font-weight:600;cursor:pointer;}
.sfl-scope:hover{background:rgba(255,255,255,.12);color:rgba(255,255,255,.8);}
.sfl-scope.on{background:rgba(255,255,255,.18);color:#fff;border-color:rgba(255,255,255,.35);}
.sfl-fold,.sfl-fsp{width:12px;flex:none;font-size:10px;text-align:center;}
.sfl-fold{cursor:pointer;opacity:.6;user-select:none;}
.sfl-fold:hover{opacity:1;}
.sfl-jump{cursor:pointer;}
.sfl-jump:hover{opacity:1;text-decoration:underline;}
.sfl-own{font-size:9px;opacity:.45;white-space:nowrap;}
.sfl-par .sfl-lbl{font-weight:700;opacity:.9;}
.sfl-par0,.sfl-par1{border-top:1px solid rgba(255,255,255,.12);background:rgba(255,255,255,.04);border-radius:3px;margin-top:3px;}
.sfl-par0 .sfl-lbl{opacity:1;}
.sfl-dup{font-size:10px;opacity:.55;margin-top:4px;text-align:right;}
.sfl-total{border-top:1px solid rgba(255,255,255,.12);margin-top:6px;padding-top:7px;display:flex;justify-content:space-between;align-items:center;}
.sfl-total-lbl{font-size:10px;opacity:.5;}
.sfl-total-num{font-size:14px;font-weight:800;}
.sfl-inc{display:inline-flex;align-items:center;gap:2px;font-size:10px;color:#9aa3b2;margin-left:4px;white-space:nowrap;cursor:pointer;}
.sfl-inc+.sfl-num{margin-left:4px;}
.sfl-inc input{margin:0;width:12px;height:12px;}
.sfl-row.sfl-off .sfl-lbl,.sfl-row.sfl-off .sfl-num{opacity:.55;}
.sfl-ex-btn{background:none;border:1px solid rgba(255,255,255,.15);border-radius:3px;cursor:pointer;color:rgba(255,255,255,.3);font-size:10px;font-weight:700;padding:0px 4px;line-height:16px;margin-left:2px;transition:.12s;}
.sfl-ex-btn:hover{color:#fff;border-color:rgba(255,255,255,.5);background:rgba(255,255,255,.1);}
.sfl-ex-in{color:var(--mint);border-color:var(--mint);opacity:.45;}
.sfl-ex-in:hover{color:var(--mint);border-color:var(--mint);opacity:1;}

.bam{width:100%;padding:8px;border:1.5px dashed #CCC;border-radius:6px;background:none;
     color:#888;cursor:pointer;font-size:12px;margin-top:7px;transition:.15s;}
.bam:hover{border-color:var(--mint);color:var(--mint);}
.bsv{background:var(--mint);color:var(--dark);padding:8px 18px;border:none;border-radius:6px;cursor:pointer;font-weight:600;font-size:13px;}
.bca{background:#EEE;color:#555;padding:8px 18px;border:none;border-radius:6px;cursor:pointer;font-size:13px;}
.bach{background:#E8F4FF;color:#2266CC;padding:8px 14px;border:1px solid #AACCEE;border-radius:6px;cursor:pointer;font-size:13px;}
.bach:hover{background:#D0E8FF;}
.bdel{background:#FFF0F0;color:#CC3333;padding:8px 14px;border:1px solid #FFCCCC;
      border-radius:6px;cursor:pointer;font-size:13px;margin-right:auto;}

/* ── Status + Zoom ───────────────────────────────── */
#stbar{
  position:fixed;bottom:0;left:0;right:0;height:26px;z-index:1000;
  background:var(--stbar-bg);color:rgba(255,255,255,.65);
  display:flex;align-items:center;padding:0 14px;font-size:11px;gap:14px;
}
#zhint{
  position:fixed;bottom:66px;left:50%;transform:translateX(-50%);
  background:var(--coral);color:#fff;padding:7px 18px;
  border-radius:20px;font-size:13px;font-weight:600;
  pointer-events:none;z-index:500;display:none;
}
#zhint.show{display:block;}
#zctrl{
  display:flex;flex-direction:row;align-items:center;gap:6px;margin-left:4px;
}
.zb{width:22px;height:22px;border-radius:5px;border:none;background:rgba(255,255,255,.1);
    cursor:pointer;font-size:12px;display:flex;align-items:center;justify-content:center;
    color:#fff;transition:.12s;font-weight:700;}
.zb:hover{background:var(--mint);color:var(--dark);}
#zpct{font-size:10px;font-weight:700;color:rgba(255,255,255,.7);min-width:30px;text-align:center;
      letter-spacing:.3px;}
#zslider{
  width:100px;cursor:pointer;accent-color:var(--mint);
}
/* ── 시트 탭 바 (엑셀식) ──────────────────────────── */
#sheetbar{
  position:fixed;bottom:26px;left:0;right:0;height:30px;z-index:1000;
  background:#232327;display:flex;align-items:flex-end;padding:0 8px;gap:2px;
  overflow-x:auto;overflow-y:hidden;scrollbar-width:none;
  border-top:1px solid rgba(255,255,255,.07);
}
#sheetbar::-webkit-scrollbar{display:none;}
.sht{
  display:flex;align-items:center;gap:6px;flex-shrink:0;
  padding:5px 14px;font-size:12px;color:rgba(255,255,255,.55);
  background:rgba(255,255,255,.04);border:none;border-radius:6px 6px 0 0;
  cursor:pointer;white-space:nowrap;max-width:180px;
}
.sht:hover{background:rgba(255,255,255,.1);color:rgba(255,255,255,.8);}
.sht.active{background:var(--bg);color:#222;font-weight:700;}
.sht .sht-x{border:none;background:none;color:inherit;opacity:.45;cursor:pointer;font-size:11px;padding:0 1px;line-height:1;}
.sht .sht-x:hover{opacity:1;color:#E33;}
.sht-add{flex-shrink:0;border:none;background:none;color:rgba(255,255,255,.5);font-size:14px;font-weight:700;cursor:pointer;padding:4px 10px;border-radius:5px;}
.sht-add:hover{background:rgba(255,255,255,.12);color:#fff;}
/* ── 읽기 전용 모드 (관리자 잠금) ─────────────────── */
body.ro .nact{display:none!important;}
body.ro .adm-only{display:none!important;}
body.ro .nd{cursor:default;}
body.ro .nd .mr{cursor:default;}
body.ro .sfl-ex-btn{display:none;}
#ro-badge{color:#FFB347;font-weight:600;}
/* 파일 재연결 배너 */
#file-banner{
  position:fixed;top:58px;left:50%;transform:translateX(-50%);z-index:1500;
  background:var(--dark);color:#fff;border:1px solid rgba(64,210,167,.5);
  border-radius:8px;padding:8px 14px;font-size:13px;display:none;
  align-items:center;gap:10px;box-shadow:0 4px 16px rgba(0,0,0,.3);
}
#file-banner.show{display:flex;}
#file-banner button{padding:5px 14px;border:none;border-radius:5px;background:var(--mint);
  color:var(--dark);font-weight:700;font-size:12px;cursor:pointer;}
/* 비밀번호 모달 */
#pwov{position:fixed;inset:0;background:rgba(0,0,0,.5);z-index:4000;display:none;align-items:center;justify-content:center;}
#pwov.show{display:flex;}
#pwmodal{background:#fff;border-radius:12px;width:360px;padding:24px 26px;box-shadow:0 8px 40px rgba(0,0,0,.35);}
#pwmodal h3{font-size:15px;font-weight:700;color:#2C2C2C;margin-bottom:14px;}
#pw-status{font-size:12px;margin-bottom:10px;min-height:16px;color:#CC3333;}
#present-exit{display:none;position:fixed;top:10px;right:14px;z-index:5000;padding:7px 14px;border-radius:6px;border:1px solid rgba(255,255,255,.3);background:rgba(30,30,30,.85);color:#fff;font-size:12px;font-weight:600;cursor:pointer;}
body.present #present-exit{display:block;}
body.present #topbar,body.present #tb-reveal,body.present #stbar,body.present #lint-panel,body.present #cmp-panel,body.present .nact,body.present .anchor-dot,body.present .dd,body.present #statsfl,body.present #sheetbar{display:none!important;}
body.present #wrap,body.present #grid-bg{top:0!important;bottom:0!important;}
.nd.srch-hit{outline:3px solid #FFB347;outline-offset:2px;}
.nd.srch-hit.srch-cur{outline:4px solid #FF7A00;outline-offset:2px;}
.mr.srch-row{background:#FFF7B0!important;}
#srch-box{display:inline-flex;align-items:center;gap:6px;}
#srch-input{width:190px;padding:3px 8px;border-radius:5px;border:1px solid rgba(255,255,255,.3);font-size:12px;}
#srch-count{color:#fff;font-size:12px;min-width:36px;}
body.present #srch-box,body.present #srch-btn{display:none!important;}
#treeview{position:fixed;top:50px;left:0;bottom:56px;width:360px;max-width:calc(100vw - 32px);z-index:1200;background:#fff;color:#222;box-shadow:2px 0 14px rgba(0,0,0,.3);display:none;flex-direction:column;font-size:13px;}
#topbar.tb-hidden ~ #treeview,#treeview.tv-notb{top:0;}
#treeview.tv-open{display:flex!important;}
.tv-head{flex:none;display:flex;align-items:center;justify-content:space-between;padding:10px 12px;border-bottom:1px solid #eee;font-weight:700;}
.tv-close{border:0;background:none;cursor:pointer;font-size:15px;color:#555;}
.tv-hbtns{display:flex;align-items:center;gap:6px;}
.tv-txtbtn,.tv-copy{border:1px solid #ccc;background:#fff;border-radius:5px;padding:3px 9px;font-size:12px;cursor:pointer;color:#333;}
.tv-txtbtn[aria-pressed="true"]{background:#2a6a4a;border-color:#2a6a4a;color:#fff;}
.tv-text{flex:1;display:flex;flex-direction:column;min-height:0;padding:8px 10px;gap:6px;}
.tv-tbar{display:flex;align-items:center;gap:10px;font-size:12px;}
.tv-copied{color:#2a6a4a;font-size:12px;}
.tv-ta{flex:1;min-height:0;width:100%;box-sizing:border-box;font:12px/1.5 Consolas,'Noto Sans KR',monospace;white-space:pre;resize:none;border:1px solid #ddd;border-radius:5px;padding:6px;color:#222;}
.tv-acts{display:none;margin-left:auto;gap:2px;flex:none;}
.tv-row:hover .tv-acts,.tv-row:focus-within .tv-acts,.tv-row.tv-sel .tv-acts{display:inline-flex;}
.tv-act{border:1px solid #d0d6d2;background:#fff;border-radius:4px;width:22px;height:22px;padding:0;font-size:12px;line-height:20px;cursor:pointer;color:#2a5a40;}
.tv-act:disabled{opacity:.35;cursor:default;}
.tv-body{flex:1;overflow-y:auto;padding:4px 0;}
.tv-row,.tv-mem{display:flex;align-items:center;gap:6px;padding:4px 10px;white-space:nowrap;}
.tv-row:hover{background:#f3f6f4;}
.tv-row.tv-sel{background:#e3efe8;box-shadow:inset 3px 0 0 #2a6a4a;}
.tv-tog{width:14px;flex:none;cursor:pointer;color:#666;text-align:center;}
.tv-title{cursor:pointer;overflow:hidden;text-overflow:ellipsis;font-weight:600;}
.tv-title:hover{text-decoration:underline;}
.tv-cnt{cursor:pointer;font-size:11px;color:#2a6a4a;background:#e6f2ec;border-radius:8px;padding:0 6px;flex:none;}
.tv-mem{color:#222;font-size:12px;}
.tv-mem .tv-sub{color:#999;}
.tv-head2{padding:10px 12px 4px;font-size:11px;font-weight:700;color:#8a6d00;border-top:1px solid #eee;margin-top:6px;}
body.present #treeview,body.present #btn-tree{display:none!important;}
@media print{#treeview,#treeview.tv-open{display:none!important;}}
#print-stats{display:none;}
#chart-head{position:absolute;display:none;height:36px;line-height:36px;font-size:20px;font-weight:700;color:#222;white-space:nowrap;overflow:hidden;pointer-events:none;}  /* 조직도 이름 · 기준일 (철님 10-20) - 차트 좌표의 윗 띠, 인쇄·PNG와 같은 자리 */
#print-head{display:none;}
#print-pages{display:none;}
#prov{position:fixed;inset:0;background:rgba(0,0,0,.35);display:none;align-items:center;justify-content:center;z-index:3000;}
#prov.show{display:flex;}
.prmodal{background:#fff;border-radius:12px;padding:18px 22px 16px;width:360px;max-width:calc(100vw - 32px);box-shadow:0 8px 40px rgba(0,0,0,.3);}
.prmodal h3{font-size:15px;font-weight:700;color:#222;margin:0 0 12px;}
.pr-row{display:flex;align-items:center;gap:8px;padding:9px 10px;border:1px solid #DADADA;border-radius:8px;margin-bottom:6px;cursor:pointer;font-size:13px;color:#222;}
.pr-row:has(input:checked){border-color:#3A9E85;background:#F2FBF8;}
.pr-e{margin-left:auto;font-size:12px;color:#555;white-space:nowrap;}
.pr-note{font-size:11px;color:#666;margin:8px 0 14px;line-height:1.5;}
.pr-foot{display:flex;justify-content:flex-end;gap:8px;}
@media print{
  #print-head{display:block;position:fixed;font-weight:700;color:#222;white-space:nowrap;overflow:hidden;z-index:50;line-height:1;}
  #print-stats{display:block;position:fixed;left:20px;top:20px;width:150px;box-sizing:border-box;background:#fff;border:1px solid #d0d0d0;font-size:11px;color:#333;z-index:50;}
  #print-stats .ps-hd{background:#2b2f36;color:#fff;font-weight:700;font-size:12px;padding:5px 10px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
  #print-stats .ps-row{display:flex;align-items:center;gap:6px;padding:2px 10px;}
  #print-stats .ps-row i{width:8px;height:8px;flex:none;}
  #print-stats .ps-row span{flex:1;}
  #print-stats .ps-tot{display:flex;justify-content:space-between;font-weight:700;font-size:12px;border-top:1px solid #e4e4e4;margin:4px 8px 0;padding:4px 2px 6px;}
  #print-stats .ps-ex{color:#999;font-size:10px;padding:2px 10px;}
}
@media print{
  #srch-box,#srch-btn{display:none!important;}
  .nd.srch-hit,.nd.srch-hit.srch-cur{outline:none!important;}
  .mr.srch-row{background:inherit!important;}
  body.cmp-noout .mr[data-cmp]{background:inherit!important;}
  body.cmp-noout .mr[data-cmp]::after{content:none!important;display:none!important;}
  body.cmp-noout .nd[data-cmp]{outline:none!important;}
  @page{size:A4 landscape;margin:0}
  body{-webkit-print-color-adjust:exact;print-color-adjust:exact;}
  *{-webkit-print-color-adjust:exact;print-color-adjust:exact;}
  #topbar,#tb-reveal,#stbar,#lint-panel,#cmp-panel,#statsfl,#sheetbar,.dd,#present-exit,#ctxmenu,#grid-bg,[id$="ov"],.modal,.overlay{display:none!important;}
  html,body{width:1123px;height:794px;overflow:hidden!important;margin:0;background:#fff;}
  #wrap{position:static!important;overflow:visible!important;top:0!important;left:0!important;right:auto!important;bottom:auto!important;width:1123px;height:794px;}
  #canvas{min-width:0!important;min-height:0!important;}
}

.ctog{position:absolute;left:50%;top:100%;transform:translateX(-50%) scale(var(--ctog-k,1));transform-origin:50% 0;min-width:18px;height:18px;padding:0 4px;box-sizing:border-box;border-radius:9px;border:0;background:#3a3a3a;color:#fff;font:11px/16px sans-serif;text-align:center;cursor:pointer;z-index:5;opacity:0;visibility:hidden;pointer-events:none;transition:opacity .15s;}
/* 가로 배치(posOrient right/left)에서는 자식이 있는 쪽 가장자리에, 세로 중앙으로 — 멤버 행을 덮지 않도록 가장자리 바깥에 붙인다 */
.ctog-r{left:100%;top:50%;transform:translateY(-50%) scale(var(--ctog-k,1));transform-origin:0 50%;}
.ctog-l{left:auto;right:100%;top:50%;transform:translateY(-50%) scale(var(--ctog-k,1));transform-origin:100% 50%;}
.nd:hover .ctog,.ctog.ctog-on{opacity:1;visibility:visible;pointer-events:auto;}
.ctog:hover{background:#000;}
@media print{.ctog,#btn-expand-all{display:none!important;}}
 @media print{@page{size:A3 landscape;margin:0} html,body{width:1587px!important;height:1123px!important;} #wrap{width:1587px!important;height:1123px!important;}}

sp4.css:
/* ── Brand Colors ─────────────────────────────── */
:root {
  --dark:   #2C2C2C;
  --gray:   #4F4F4F;
  --mint:   #40D2A7;
  --coral:  #FF8770;
  --sky:    #60DCF8;
  --bg:     #ECEEF3;
  --white:  #FFFFFF;
  --border: #E2E4EA;
  --nw: 228px;
  --hh: 70px;
  --mh: 50px;
  --fs-en: 12px;
  --fs-ko: 10px;
  --fs-mn: 11px;
  --fs-mf: 9px;
  --lh-h: 1.2;
  --lh-c: 1.2;
  --band-w: 12px;
  --stroke-w: 1.8;
  --stroke-dash-w: 1.5;
  --card-radius: 8px;
  --shadow-a:    0.11;
  --fs-mr2: 9px;
  --fs-ma:  9px;
  /* 카드 헤더 배경 */
  --hdr-top:  #1A1A1A; --hdr-l1: #2C2C2C;
  --hdr-l2:   #383838; --hdr-l3: #424242;
  --hdr-l4:   #4A4A4A; --hdr-l5: #525252; --hdr-tf: #30304A;
  --hdr-side: #323232;
  /* 타입별 기본 띠색 */
  --band-top: #40D2A7; --band-l1: #40D2A7;
  --band-l2:  #60DCF8; --band-l3: #60DCF8;
  --band-l4:  #A78BFA; --band-l5: #A78BFA; --band-tf: #FF8770;
  --band-side:#FF8770;
  /* 카드 본문 */
  --card-bg:    #FFFFFF;
  --row-even:   #FAFBFD;
  --row-border: #F2F3F6;
  /* 연결선 */
  --conn-solid: #7D879A;
  --conn-dash:  #FF8770;
  /* 그리드 */
  --grid-dot:   #B0B6C4;
  /* 플로팅 패널 / 상태바 */
  --stats-bg:   #1C1C20;
  --stbar-bg:   #1A1A1A;
  /* 텍스트 */
  --txt-hdr-en: #FFFFFF;
  --txt-hdr-ko: #F4F4F4;
  --txt-mn:     #222222;
  --txt-mf:     #666666;
  --txt-mr2:    #707070;
  --txt-ma:    #5F6F91;
  /* 상태 */
  --st-active:  #40D2A7; --st-joining: #60DCF8;
  --st-leaving: #FF8770; --st-needed:  #FFB347; --st-hiring: #A78BFA;
}
*{box-sizing:border-box;margin:0;padding:0;}
body{font-family:'Noto Sans KR',-apple-system,sans-serif;background:var(--bg);overflow:hidden;height:100vh;user-select:none;}

/* ── Topbar ───────────────────────────────────────── */
#topbar{
  position:fixed;top:0;left:0;right:0;height:50px;z-index:1000;
  background:var(--dark);color:#fff;
  display:flex;align-items:center;padding:0 18px;gap:9px;
  box-shadow:0 2px 10px rgba(0,0,0,.4);
  overflow-x:auto;overflow-y:hidden;scrollbar-width:none;
}
#topbar::-webkit-scrollbar{display:none;}
#topbar>*{flex-shrink:0;}
.tl{font-size:15px;font-weight:800;letter-spacing:2px;color:var(--mint);white-space:nowrap;}
.tsub{font-size:12px;color:rgba(255,255,255,.62);flex:1;margin-left:8px;white-space:nowrap;min-width:0;overflow:hidden;text-overflow:ellipsis;flex-shrink:1;}
.tb{white-space:nowrap;}
.tb{padding:6px 13px;border-radius:5px;border:none;cursor:pointer;font-size:12px;font-weight:600;transition:.15s;}
.tb-g{background:rgba(255,255,255,.1);color:#fff;border:1px solid rgba(255,255,255,.2);}
.tb-g:hover{background:rgba(255,255,255,.2);}
.tb-m{background:var(--mint);color:var(--dark);}
.tb-m:hover{filter:brightness(1.1);}
.tb.act{background:var(--coral)!important;color:#fff!important;}
.tdv{width:1px;height:22px;background:rgba(255,255,255,.15);margin:0 3px;}
#topbar.tb-hidden{display:none;}
.tb-arrow{background:transparent;border:none;color:#fff;cursor:pointer;font-size:12px;line-height:1;padding:5px 7px;border-radius:5px;transition:.15s;}
.tb-arrow:hover{background:rgba(255,255,255,.15);}
#tb-hide{margin-right:12px;}
#topbar>.tsub{flex-shrink:1;}
#topbar.tb-tight{gap:5px;}
#topbar.tb-tight .tb{padding:6px 9px;}
#topbar.tb-compact .tdv{display:none;}
#topbar.tb-compact .tb[data-icon]{font-size:0;padding:6px 9px;}
#topbar.tb-compact .tb[data-icon]::before{content:attr(data-icon);font-size:12px;}
#tb-more-panel{position:fixed;top:54px;right:8px;z-index:1050;display:none;flex-direction:column;align-items:stretch;gap:6px;
  background:var(--dark);border:1px solid rgba(255,255,255,.2);border-radius:8px;padding:8px;box-shadow:0 6px 20px rgba(0,0,0,.45);
  max-height:calc(100vh - 64px);max-width:calc(100vw - 16px);overflow-y:auto;}
#tb-more-panel.open{display:flex;}
#topbar,#topbar *,#tb-more-panel,#tb-more-panel *{transition:none!important;}
#tb-more-panel>*{flex-shrink:0;}
#tb-more-panel .tb{text-align:left;}
#tb-more-panel .dd-wrap{display:block;}
#tb-more-panel .dd-wrap>.tb{width:100%;}
body.present #tb-more,body.present #tb-more-panel{display:none!important;}
@media print{#tb-more,#tb-more-panel{display:none!important;}}
#tb-reveal{position:fixed;top:11px;right:30px;z-index:1100;display:none;align-items:center;justify-content:center;width:30px;height:26px;border-radius:6px;background:var(--dark);color:var(--mint);border:1px solid rgba(255,255,255,.2);cursor:pointer;font-size:12px;box-shadow:0 2px 8px rgba(0,0,0,.3);}
#tb-reveal:hover{background:var(--mint);color:var(--dark);}
/* Cloud sync button */
.tb-cloud{max-width:240px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;background:rgba(255,255,255,.08);color:#aaa;border:1px solid rgba(255,255,255,.15);position:relative;}
.tb-cloud.conn{color:#fff;border-color:rgba(64,210,167,.5);background:rgba(64,210,167,.12);}
.cloud-dot{display:none;width:7px;height:7px;border-radius:50%;background:#40D2A7;position:absolute;top:5px;right:5px;box-shadow:0 0 4px #40D2A7;}
.tb-cloud.conn .cloud-dot{display:block;}
/* Cloud modal */
#cloudov{position:fixed;inset:0;background:rgba(0,0,0,.5);z-index:4000;display:none;align-items:center;justify-content:center;}
#cloudov.show{display:flex;}
#cloudmodal{background:#fff;border-radius:12px;width:420px;padding:24px 26px;box-shadow:0 8px 40px rgba(0,0,0,.35);}
#cloudmodal h3{font-size:15px;font-weight:700;color:#2C2C2C;margin-bottom:16px;}
.cm-lbl{font-size:12px;color:#555;display:block;margin-bottom:5px;font-weight:600;}
.cm-inp{width:100%;padding:8px 10px;border:1.5px solid #DDD;border-radius:6px;font-size:13px;margin-bottom:12px;outline:none;transition:.15s;}
.cm-inp:focus{border-color:#40D2A7;}
#cm-status{font-size:12px;margin-bottom:12px;min-height:18px;}
.cm-foot{display:flex;gap:8px;justify-content:flex-end;margin-top:4px;}

/* ── Canvas ───────────────────────────────────────── */
#wrap{
  position:fixed;top:50px;left:0;right:0;bottom:56px;
  overflow:auto;
}
#wrap.panning{cursor:grab;}
#wrap.panning:active{cursor:grabbing;}
#wrap.connect-mode{cursor:crosshair;}
#canvas{
  position:relative;
  transform-origin:0 0;
  min-width:1800px;min-height:1020px;
}
.tfzone{position:absolute;z-index:0;box-sizing:border-box;pointer-events:none;background:rgba(255,193,7,.10);border:2px dashed #c9a227;border-radius:16px;}
.tfzone-t{position:absolute;left:12px;top:6px;font:bold 12px/16px sans-serif;color:#6E5700;white-space:nowrap;}
.tfowner{position:absolute;z-index:0;box-sizing:border-box;height:16px;max-width:200px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font:11px/16px sans-serif;color:#6E5700;pointer-events:none;}
@media print{.tfzone,.tfowner{display:block!important;-webkit-print-color-adjust:exact;print-color-adjust:exact;}}
/* dot grid — fixed overlay, dynamically positioned via JS */
#grid-bg{
  position:fixed;top:50px;left:0;right:0;bottom:56px;
  pointer-events:none;z-index:0;opacity:.5;
  background-image:radial-gradient(circle at 0 0,var(--grid-dot) 1px,transparent 1px);
}

/* ── SVG Connections ──────────────────────────────── */
#svgl{position:absolute;top:0;left:0;pointer-events:none;}
.cpath{fill:none;stroke:var(--conn-solid);stroke-width:var(--stroke-w);}
.cpath-dash{fill:none;stroke:var(--conn-dash);stroke-width:var(--stroke-dash-w);stroke-dasharray:7 4;}
body:not(.printing) #svgl .cpath{stroke-width:max(calc(var(--stroke-w) * 1px),var(--line-min,0px));}  /* 화면을 줄여도 선이 1.3px 아래로 가늘어지지 않게 (철님 10-23) */
body:not(.printing) #svgl .cpath-dash{stroke-width:max(calc(var(--stroke-dash-w) * 1px),var(--line-min,0px));}
@media print{#svgl .cpath{stroke-width:var(--stroke-w)!important;}#svgl .cpath-dash{stroke-width:var(--stroke-dash-w)!important;}}
.cpath-hl-dash{stroke:var(--conn-dash)!important;}
.chit{fill:none;stroke:transparent;stroke-width:14;pointer-events:stroke;cursor:pointer;}
.chit:hover~.cpath,.chit:hover~.cpath-dash{stroke-opacity:.5;}
/* 연결선 선택 하이라이트 */
.cpath-hl{fill:none;stroke:var(--sky);stroke-width:4.5;opacity:.45;}
.cpath-hl-dash{fill:none;stroke:var(--coral);stroke-width:3.5;opacity:.45;stroke-dasharray:7 4;}
.nd.conn-hl{box-shadow:0 0 0 2.5px var(--sky),0 4px 18px rgba(0,0,0,.18)!important;}
/* 앵커 오버레이 */
#anchor-overlay{position:absolute;top:0;left:0;pointer-events:none;z-index:60;}
.anchor-dot{
  position:absolute;width:14px;height:14px;border-radius:50%;
  border:2.5px solid var(--coral);background:rgba(255,255,255,.92);
  transform:translate(-50%,-50%);pointer-events:all;cursor:crosshair;
  transition:.1s;box-shadow:0 1px 5px rgba(0,0,0,.18);
}
.anchor-dot.active{background:var(--coral);}
.anchor-dot.drop-target{border-color:var(--sky);background:rgba(96,220,248,.2);transform:translate(-50%,-50%) scale(1.25);}
/* 드롭다운 메뉴 */
.dd-wrap{position:relative;display:inline-block;}
.dd{position:fixed;z-index:2000;
  background:#fff;border-radius:8px;box-shadow:0 5px 18px rgba(0,0,0,.2);
  padding:4px 0;min-width:130px;border:1px solid rgba(0,0,0,.07);display:none;}
.dd.open{display:block;}
.ddi{display:block;width:100%;padding:9px 15px;text-align:left;border:none;
  background:none;cursor:pointer;font-size:12px;color:#333;white-space:nowrap;}
.ddi:hover{background:#F3F5F9;}
/* 웨이포인트 핸들 */
.way-handle{fill:var(--sky);stroke:#fff;stroke-width:2;cursor:ns-resize;}
/* ── Options Popup ────────────────────────────────── */
#optov{position:fixed;inset:0;background:rgba(0,0,0,.45);z-index:3000;display:none;align-items:flex-start;justify-content:center;padding-top:60px;}
#optov.show{display:flex;}
#optmodal{background:#fff;border-radius:12px;width:520px;max-height:82vh;overflow-y:auto;box-shadow:0 8px 40px rgba(0,0,0,.3);}
.opt-head{padding:16px 22px 12px;border-bottom:1px solid #EEE;display:flex;align-items:center;justify-content:space-between;position:sticky;top:0;background:#fff;z-index:1;}
.opt-head h2{font-size:15px;font-weight:700;color:var(--dark);}
.opt-body{padding:6px 0 16px;}
.opt-sec{padding:10px 22px 4px;}
.opt-sec-title{font-size:10px;font-weight:700;color:#6B6B6B;letter-spacing:1.5px;text-transform:uppercase;margin-bottom:10px;padding-bottom:4px;border-bottom:1px solid #F0F0F0;}
.opt-sec-title[role=button]{cursor:pointer;user-select:none;}
.opt-sec.collapsed>*:not(.opt-sec-title){display:none;}
.opt-sec.collapsed>.opt-sec-title{margin-bottom:0;}
.opt-row{display:flex;align-items:center;gap:10px;margin-bottom:10px;}
.pre-row{display:flex;align-items:center;gap:6px;margin-bottom:6px;}
.pre-name{flex:1;min-width:0;border:1px solid #D0D0D0;border-radius:5px;padding:4px 6px;font-size:12px;}
.pre-b{font-size:11px;padding:4px 8px;border:1px solid #C8C8C8;border-radius:5px;background:#fff;color:#333;cursor:pointer;white-space:nowrap;}
.pre-b:hover:not(:disabled){background:#F2F2F2;}
.pre-b:disabled{opacity:.45;cursor:default;}
.pre-at{font-size:10px;color:#666;width:62px;text-align:right;white-space:nowrap;}
.pre-hint{font-size:11px;color:#666;line-height:1.5;margin-top:2px;}
.opt-lbl{font-size:12px;color:#555;min-width:100px;}
.opt-val{font-size:11px;color:#6B6B6B;min-width:32px;text-align:right;}
.opt-slider{flex:1;accent-color:var(--mint);cursor:pointer;}
.opt-color{width:32px;height:28px;border:1.5px solid #DDD;border-radius:5px;cursor:pointer;padding:2px;}
.opt-color-row{display:flex;align-items:center;gap:8px;margin-bottom:8px;}
.opt-color-lbl{font-size:12px;color:#555;flex:1;}
.opt-color-dot{width:10px;height:10px;border-radius:50%;flex-shrink:0;box-shadow:inset 0 0 0 1px rgba(0,0,0,.18);} /* a white swatch (헤더 제목) was invisible on the panel */
.opt-foot{padding:12px 22px;border-top:1px solid #EEE;display:flex;justify-content:flex-end;gap:8px;}
/* 컬러 헥스 인풋 (피커 + 6자리 텍스트) */
.chex{display:inline-flex;align-items:center;gap:3px;}
.chex-c{width:28px;height:28px;padding:2px;border:1.5px solid #DDD;border-radius:5px;cursor:pointer;flex-shrink:0;}
.chex-hash{font-size:12px;color:#888;user-select:none;line-height:1;}
.chex-t{width:60px;padding:4px 5px;border:1px solid #DDD;border-radius:4px;font-size:12px;font-family:monospace;letter-spacing:1px;text-transform:uppercase;}
.chex-t:focus{border-color:var(--mint);outline:none;}
/* 멤버 상태 드롭다운 (수정 모달 내) */
.mer select{padding:4px 6px;border:1px solid #DDD;border-radius:4px;font-size:11px;background:#fff;cursor:pointer;}
/* 우클릭 컨텍스트 메뉴 */
#ctxmenu{position:fixed;z-index:3000;background:#fff;border-radius:8px;
  box-shadow:0 6px 24px rgba(0,0,0,.22);padding:5px 0;min-width:150px;display:none;}
#ctxmenu.show{display:block;}
.ctx-item{padding:9px 16px;font-size:13px;cursor:pointer;display:flex;align-items:center;gap:8px;color:#333;}
.ctx-item:hover{background:#F5F7FA;}
.ctx-del{color:#CC3333;}

/* ── Node Cards ───────────────────────────────────── */
.nd{
  position:absolute;width:var(--nw);
  background:var(--white);border-radius:var(--card-radius);
  box-shadow:0 2px 8px rgba(0,0,0,var(--shadow-a));
  overflow:visible;transition:box-shadow .2s;  /* 접기 토글(.ctog)이 카드 가장자리 바깥에 걸치므로 모서리 클리핑은 .nh/.nb가 맡는다 */
}
.nd:hover{box-shadow:0 6px 20px rgba(0,0,0,var(--shadow-a));}
.nd{cursor:move;}
.nd.lint-bad{outline:3px solid #dc2626;outline-offset:2px;}
.nd.lint-flash{animation:lintflash .3s ease 3;}
@keyframes lintflash{50%{filter:brightness(1.4);}}
#lint-panel{display:none;position:fixed;z-index:9999;background:#fff;color:#111;border:1px solid #ccc;border-radius:6px;box-shadow:0 4px 16px rgba(0,0,0,.25);padding:8px;width:300px;max-height:60vh;overflow:auto;font-size:12px;}
.lint-item{padding:4px 2px;cursor:pointer;border-top:1px solid #eee;}
.lint-item:hover{background:#fee2e2;}
.nd .mr{cursor:grab;}
.mr[data-cmp]::after{position:absolute;right:2px;top:1px;font-size:9px;line-height:1;padding:1px 3px;border-radius:3px;color:#fff;pointer-events:none;}
.mr[data-cmp="new"]{background:rgba(46,160,67,.18);}
.mr[data-cmp="new"]::after{content:'신규';background:#2ea043;}
.mr[data-cmp="moved"]{background:rgba(56,139,253,.18);}
.mr[data-cmp="moved"]::after{content:'이동';background:#388bfd;}
.mr[data-cmp="changed"]{background:rgba(227,160,8,.22);}
.mr[data-cmp="changed"]::after{content:'변경';background:#d29922;}
.nd[data-cmp="new"]{outline:2px dashed #2ea043;outline-offset:2px;}
#cmp-panel{position:fixed;top:60px;right:12px;z-index:900;background:#fff;color:#222;border:1px solid #ccc;border-radius:6px;box-shadow:0 2px 10px rgba(0,0,0,.2);padding:8px 10px;width:340px;max-height:60vh;overflow:auto;font-size:12px;}
#cmp-panel .cmp-h{display:flex;justify-content:space-between;align-items:center;gap:8px;margin-bottom:6px;}
#cmp-panel .cmp-err{color:#c00;}
#cmp-panel .cmp-cnt{margin-bottom:6px;font-weight:600;}
#cmp-panel{width:380px!important;}
#cmp-panel .cmp-cnt{display:flex;flex-wrap:wrap;gap:4px;font-weight:400;}
#cmp-panel .cmp-chip{background:#f1f3f6;border-radius:10px;padding:1px 8px;font-size:12px;}
#cmp-panel .cmp-chip[data-k=join]{background:#e3f6ee}#cmp-panel .cmp-chip[data-k=leave]{background:#fde8e4}#cmp-panel .cmp-chip[data-k=move]{background:#e6f0fd}#cmp-panel .cmp-chip[data-k=seat]{background:#fff3df}
#cmp-panel .cmp-out{display:block;font-size:12px;color:#555;margin:6px 0 2px;}
#cmp-panel .cmp-sec{margin-top:8px;}
#cmp-panel .cmp-sec-h{font-weight:700;font-size:12px;color:#333;border-bottom:2px solid #d8dde6;padding-bottom:2px;}
#cmp-panel .cmp-tbl{width:100%;border-collapse:collapse;font-size:12px;}
#cmp-panel .cmp-tbl td{padding:3px 4px;border-bottom:1px solid #eee;vertical-align:top;}
#cmp-panel .cmp-tbl td.c0{font-weight:600;white-space:nowrap;}
#cmp-panel .cmp-tbl td.c1{color:#556;}
#cmp-panel .cmp-tbl td.c2{color:#777;}
.mr[data-cmp="seat"]{background:rgba(255,179,71,.22);}
.mr[data-cmp="seat"]::after{content:'공석';background:#e08a00;}
#cmp-panel .cmp-item{cursor:pointer;}
#cmp-panel .cmp-item:hover td{background:#f6f8fb;}
.nd .mr:active{cursor:grabbing;}
.nd .nact button{cursor:pointer;}
.nd.sel{outline:2.5px solid var(--sky);outline-offset:2px;}
.nd.csrc{outline:2.5px solid var(--coral);outline-offset:2px;}

/* Header */
.nh{
  height:var(--hh);padding:8px 12px 8px 16px;
  display:flex;flex-direction:column;justify-content:center;
  cursor:move;position:relative;
  border-radius:var(--card-radius) var(--card-radius) 0 0;overflow:hidden;
}
.nh::before{content:'';position:absolute;left:0;top:0;bottom:0;width:var(--band-w);background:var(--band-color,var(--mint));}
.t-top {--band-color:var(--band-top);} .t-top  .nh{background:var(--hdr-top);}
.t-l1  {--band-color:var(--band-l1);}  .t-l1   .nh{background:var(--hdr-l1);}
.t-l2  {--band-color:var(--band-l2);}  .t-l2   .nh{background:var(--hdr-l2);}
.t-l3  {--band-color:var(--band-l3);}  .t-l3   .nh{background:var(--hdr-l3);} .t-l3 .nh::before{opacity:.7;}
.t-l4  {--band-color:var(--band-l4);}  .t-l4   .nh{background:var(--hdr-l4);} .t-l4 .nh::before{opacity:.6;}
.t-l5  {--band-color:var(--band-l5);}  .t-l5   .nh{background:var(--hdr-l5);} .t-l5 .nh::before{opacity:.5;}
.t-tf  {--band-color:var(--band-tf);}  .t-tf   .nh{background:var(--hdr-tf);}
.t-side{--band-color:var(--band-side);}.t-side .nh{background:var(--hdr-side);}

.nen{font-size:var(--fs-en);font-weight:700;color:var(--txt-hdr-en);letter-spacing:.6px;text-transform:uppercase;padding-left:2px;line-height:var(--lh-h);}
.nko{font-size:var(--fs-ko);color:var(--txt-hdr-ko);padding-left:2px;margin-top:2px;line-height:var(--lh-h);}

/* Action buttons (hover) */
.nact{position:absolute;top:6px;right:7px;opacity:0;transition:.15s;}
.ncnt{position:absolute;top:calc(3px + var(--cnt-dy,0px));right:calc(36px + var(--cnt-dx,0px));font-size:var(--cnt-fs,9px);line-height:var(--cnt-lh,12px);padding:0 var(--cnt-px,6px);border-radius:8px;background:rgba(0,0,0,.55);color:#fff;box-shadow:inset 0 0 0 1px rgba(255,255,255,.28);pointer-events:none;white-space:nowrap;}  /* 흰 글자 대비 4.5 이상: 흰 헤더 위에서도 4.76 */
.ncnt{z-index:3;}
.ncnt-br{top:calc(var(--hh) - var(--cnt-lh,12px) - 4px + var(--cnt-dy,0px));}
.ncnt.ncnt-mr{top:calc(var(--hh) / 2 - var(--cnt-lh,12px) / 2 + var(--cnt-dy,0px));}
.ncnt.ncnt-badge,body.ro .ncnt.ncnt-badge,body.present .ncnt.ncnt-badge{top:var(--cnt-dy,0px);right:var(--cnt-dx,0px);transform:translate(50%,-50%);z-index:6;}
#mtip{position:fixed;display:none;z-index:99999;background:rgba(20,20,24,.95);color:#fff;font-size:11px;line-height:1.5;padding:7px 10px;border-radius:6px;max-width:260px;pointer-events:none;word-break:break-all;box-shadow:0 2px 8px rgba(0,0,0,.35);}
#mtip b{font-size:12px;}
body.present #mtip{display:none!important;}
@media print{#mtip{display:none!important;}}
.nd:hover .nact{opacity:1;}
.nab{width:22px;height:22px;border-radius:5px;border:none;cursor:pointer;font-size:12px;
     display:flex;align-items:center;justify-content:center;background:rgba(255,255,255,.2);color:#fff;transition:.15s;}
.nab:hover{background:var(--mint);color:var(--dark);}

/* Member rows */
.nb{background:var(--card-bg);border-radius:0 0 var(--card-radius) var(--card-radius);overflow:hidden;}
.nb:empty{height:10px;min-height:10px;position:relative;overflow:visible;}  /* 구성원이 없는 카드: 배치·인쇄·PNG는 머리글 + 10px 흰 마감 (EMPTY_CAP) */
.nb:empty::before{content:'＋';position:absolute;left:0;right:0;top:0;height:34px;display:flex;align-items:center;justify-content:center;background:var(--card-bg);border-radius:0 0 var(--card-radius) var(--card-radius);box-shadow:0 2px 8px rgba(0,0,0,var(--shadow-a));color:#C8CDD8;font-size:15px;}  /* 화면에서는 원래의 ＋ 본문이 마감 위에 겹쳐 보인다 (철님 10-20) - 구성원 끌어다 놓는 자리 */
body.printing .nb:empty::before{display:none!important;}
@media print{.nb:empty::before{display:none!important;}}
.mr{padding:4px 10px 4px calc(var(--band-w) + 8px);height:var(--mh);position:relative;display:flex;align-items:center;gap:0;border-top:1px solid var(--row-border);box-sizing:border-box;overflow:hidden;}
.mr:nth-child(even){background:var(--row-even);}
.nb.mcol{display:grid;padding-left:var(--band-w);background:linear-gradient(var(--band-color,var(--mint)),var(--band-color,var(--mint))) left top/var(--band-w) 100% no-repeat,var(--card-bg);}
/* 본문 색 띠 옵션(OPT.bodyBand): 켜면 1열 카드도 본문에 띠, 끄면 여러 열 카드도 머리글에만 - 열 수와 무관하게 같은 규칙 (철님 10-20) */
body.bodyband .nb{padding-left:var(--band-w);background:linear-gradient(var(--band-color,var(--mint)),var(--band-color,var(--mint))) left top/var(--band-w) 100% no-repeat,var(--card-bg);}
body:not(.bodyband) .nb.mcol{padding-left:0;background:var(--card-bg);}
:where(.nb.mcol)>.mr:nth-child(even){background:none;}
.mr.mr-ev{background:var(--row-even);}
.nb.mcol>.mr[data-cmp="new"]{background:rgba(46,160,67,.18);}
.nb.mcol>.mr[data-cmp="moved"]{background:rgba(56,139,253,.18);}
.nb.mcol>.mr[data-cmp="changed"]{background:rgba(227,160,8,.22);}
.mband{position:absolute;left:0;top:0;bottom:0;width:var(--band-w);}
.mi{flex:1;min-width:0;overflow:hidden;}
.mn-row{display:flex;align-items:flex-end;gap:8px;overflow:hidden;}
.mn{font-size:var(--fs-mn);font-weight:600;color:var(--txt-mn);line-height:var(--lh-c);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;min-width:0;flex-shrink:1;}
.mf{font-size:var(--fs-mf);color:var(--txt-mf);margin-top:1px;line-height:var(--lh-c);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}
.mr2{font-size:var(--fs-mr2);color:var(--txt-mr2);white-space:nowrap;flex-shrink:0;line-height:var(--lh-c);}
.mn-row>.mn:empty,.mn-row>.mr2:empty{display:none;}
.mst{font-size:var(--fs-mr2);line-height:1.2;color:#333;background:#fff;border:1px solid #9A9A9A;border-radius:3px;padding:0 3px;white-space:nowrap;flex-shrink:0;align-self:center;}
.ma{font-size:var(--fs-ma);color:var(--txt-ma);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;line-height:var(--lh-c);margin-top:1px;}
/* Member row drag-and-drop (move between teams) */
.mr[draggable="true"]{cursor:grab;}
.mr[draggable="true"]:active{cursor:grabbing;}
.mr.mr-dragging{opacity:.35;background:#FFF4ED!important;}
.nb.mr-drop-target{background:rgba(64,210,167,.10);box-shadow:inset 0 0 0 2px var(--mint);}
.mr.mr-drop-before{box-shadow:inset 0 2px 0 0 var(--mint)!important;}
.mr.mr-drop-after{box-shadow:inset 0 -2px 0 0 var(--mint)!important;}

/* ── Modal ───────────────────────────────────────── */
#ov{
  position:fixed;inset:0;background:rgba(0,0,0,.5);z-index:2000;
