.sfl-ex-in:hover{color:var(--mint);border-color:var(--mint);opacity:1;}

.bam{width:100%;padding:8px;border:1.5px dashed #CCC;border-radius:6px;background:none;
     color:#888;cursor:pointer;font-size:12px;margin-top:7px;transition:.15s;}
